from datetime import datetime, timezone

# service -> (max attempts, backoff cap, longest accepted Retry-After)
_PROFILES = {
    "catalog": (6, 8, 30),
    "ledger": (8, 3, 60),
    "auth": (6, 6, 20),
    "payments": (3, 1, 30),
    "ledger-export": (4, 8, 10),
    "reports": (9, 5, 120),
    "inventory": (7, 4, 90),
    "search": (10, 12, 45),
    "shipping": (8, 3, 40),
    "media": (5, 8, 15),
}
_IDEMPOTENT = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_UNSAFE = {"POST", "PATCH"}
_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
_DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_DATE_RE = re.compile(
    r"([A-Za-z]{3}), (\\d{2}) ([A-Za-z]{3}) (\\d{4}) (\\d{2}):(\\d{2}):(\\d{2}) GMT"
)


def _header(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    """Wait in seconds, or None if absent/malformed."""
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    m = _DATE_RE.fullmatch(value)
    if not m or m.group(1) not in _DAYS or m.group(3) not in _MONTHS:
        return None
    try:
        d = datetime(
            int(m.group(4)), _MONTHS.index(m.group(3)) + 1, int(m.group(2)),
            int(m.group(5)), int(m.group(6)), int(m.group(7)), tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (d - now).total_seconds())
''')
